// Extract .zip commits from Forgejo push payload
// Forgejo sends: { ref, commits: [{added,modified,removed}], repository: {full_name} }
const body = $input.item.json.body || $input.item.json;
const commits = body.commits || [];
const ref = body.ref || '';
const repoName = body.repository?.full_name || '';

// Only process main branch pushes
if (ref !== 'refs/heads/main') {
  return [];
}

// Collect all added/modified .zip files
const zipFiles = [];
for (const commit of commits) {
  for (const f of [...(commit.added || []), ...(commit.modified || [])]) {
    if (f.endsWith('.zip')) {
      zipFiles.push({ file: f, repo: repoName });
    }
  }
}

if (zipFiles.length === 0) return [];
return zipFiles.map(z => ({ json: z }));

// Save binary zip to /moodle-uploads/ inside n8n container
// n8n has /moodle-uploads mounted as a shared volume with Moodle
const fs = require('fs');
const path = require('path');

const filename = path.basename($input.item.json.file || 'package.zip');
const destPath = `/moodle-uploads/${filename}`;

const binaryData = $input.item.binary?.data;
if (!binaryData) throw new Error('No binary data from download step');

const buf = Buffer.from(binaryData.data, 'base64');
fs.writeFileSync(destPath, buf);

return [{ json: { filename, destPath, originalFile: $input.item.json.file } }];

// Read metadata.json from same folder in Forgejo (optional)
// metadata.json format: { "course_id": 5, "section": 1 }
const http = require('http');
const path = require('path');

const originalFile = $input.item.json.originalFile || '';
const folder = path.dirname(originalFile);
const metaUrl = `http://cryptex-forgejo:3000/${$input.item.json.repo || 'parth/scorm-packages'}/raw/branch/main/${folder}/metadata.json`;

return new Promise((resolve) => {
  http.get(metaUrl, (res) => {
    let data = '';
    res.on('data', c => data += c);
    res.on('end', () => {
      let meta = {};
      try { meta = JSON.parse(data); } catch(e) {}
      resolve([{ json: {
        ...$input.item.json,
        course_id: meta.course_id || null,
        section: meta.section || 0
      }}]);
    });
  }).on('error', () => {
    resolve([{ json: { ...$input.item.json, course_id: null, section: 0 } }]);
  });
});

// Parse PHP script JSON output
let result = {};
try {
  const stdout = $input.item.json.stdout || '';
  // Find the JSON line (last line of stdout)
  const lines = stdout.trim().split('\n');
  result = JSON.parse(lines[lines.length - 1]);
} catch(e) {
  result = { status: 'error', message: $input.item.json.stdout };
}
return [{ json: { ...result, filename: $input.item.json.filename } }];
